const CustomerView = () => {
    function guidGenerator() {
        var S4 = function() {
           return (((1+Math.random())*0x10000)|0).toString(16).substring(1);
        };
        return (S4()+S4()+"-"+S4()+"-"+S4()+"-"+S4()+"-"+S4()+S4()+S4());
      }

      // Set a unique key to force re-render of RenderScreen when URL params change
const key = `${'custview'}-${guidGenerator()}`;

    const [rowData, setRowData] = useState([]);
    const [selectedCustomerId, setSelectedCustomerId] = useState(null);

    const [columnDefs] = useState([
        { headerName: 'Customer ID', field: 'CustomerId', filter: true },
        { headerName: 'Name', field: 'FullName', filter: true },
        { headerName: 'Age', field: 'AGE', filter: true },
        { headerName: 'Gender', field: 'Gender', filter: true },
        { headerName: 'NationalId', field: 'NationalId', filter: true },
    ]);

    const defaultColDef = {
        sortable: true,
        filter: true,
        //floatingFilter: true,
        resizable: true,
    };

    const fetchCustomerList = async () => {

        try {
            
            const endpoints = appsettings.ApiEndpoints;
            const url = endpoints.psprst;
            const convID = generateUUID();
            const frmHdr = { convid: convID };
            const bodydata = {
                '_sp': 'GetCustomerListforDashboard',
                '_db': 'finxloan',
                'LoanRefId': ''
            }
            const data = { hdr: frmHdr, body: bodydata };
            let response = await api.post(url, data);

            return response?.data?.body?.results?.rst1
        } catch (error) {
        }
    }

    useEffect(() => {
        const fetchData = async () => {
            let customerdata = await fetchCustomerList()
            console.log(customerdata);
            setRowData(customerdata);
        }
        fetchData();
    }, []);

    const onGridReady = useCallback((params) => {
        params.api.sizeColumnsToFit();
    }, []);

    const onRowClicked = useCallback((event) => {
        
        setSelectedCustomerId(event.data.CustomerId);
    }, []);

    const handleBack = () => {
        setSelectedCustomerId(null);
    };

    return (
        <div key={key}>
            {selectedCustomerId ? (

                <Customer360Dashboard customerId={selectedCustomerId} onBack={handleBack} />
            ) : (
                <div className="ag-theme-alpine" style={{ height: '600px', width: '100%' }}>
                    <AgGridReact
                        rowData={rowData}
                        columnDefs={columnDefs}
                        defaultColDef={defaultColDef}
                        pagination={true}
                        paginationPageSize={20}
                        onGridReady={onGridReady}
                        onRowClicked={onRowClicked}
                    />
                </div>
            )}
        </div>
    );
};

export default CustomerView;
