import React, { useEffect, useState } from 'react';
import * as am5 from '@amcharts/amcharts5';
import * as am5xy from '@amcharts/amcharts5/xy';
import * as am5percent from '@amcharts/amcharts5/percent';
import am5themes_Animated from '@amcharts/amcharts5/themes/Animated';
import am5themes_Responsive from "@amcharts/amcharts5/themes/Responsive";
import 'bootstrap/dist/css/bootstrap.min.css';
import appsettings from '../appsettings.json'
import api from '../components/api/Webcall';
import profPic from "../assets/imgs/profile-img.png";
import { Link, useNavigate } from "react-router-dom";
import { generateUUID, compressLZW, decompressLZW, compressBase64, decompressBase64 } from "../components/utilities/utils";

const Customer360Dashboard = ({ customerId, onBack }) => {

  const [dashboarddata, setDashboardData] = useState(null);
  const [picurl, setPicurl] = useState(null);

  const fetchDashboardData = async () => {


    try {

      const endpoints = appsettings.ApiEndpoints;
      const url = endpoints.psprst;
      const convID = generateUUID();
      const frmHdr = { convid: convID };
      const bodydata = {
        '_sp': 'GetCustomer360Data',
        '_db': 'finxloan',
        'CustomerId': customerId
      }
      const data = { hdr: frmHdr, body: bodydata };
      let response = await api.post(url, data);
      
      if (response?.data?.body?.results?.rst1[0]?.PhotoId) {
        response.data.body.results.rst1[0]["Photourl"] = await getFileDetails(response?.data?.body?.results?.rst1[0]?.PhotoId.split("\|")[0]);
      }
      setDashboardData(response?.data?.body?.results);
    } catch (error) {
    }

  }


  const getFileDetails = async (docId) => {
    const endpoints = appsettings.ApiEndpoints;
    let docurl = null;
    docurl = endpoints.dwnld + "?docid=" + docId;
    let response = await api.get(docurl, {
      responseType: "blob", // Set responseType to 'blob'
    });
    let docdetails = response.data;
    docdetails = new Blob([docdetails], { type: "application/octet-stream" });
    return URL.createObjectURL(docdetails);
  };

  useEffect(() => {
    fetchDashboardData();

  }, [])

  useEffect(() => {
    if (!dashboarddata) return;


    let root = am5.Root.new('loanDistributionChart');
    root.setThemes([am5themes_Animated.new(root)]);
    let chart = root.container.children.push(am5percent.PieChart.new(root, { layout: root.verticalLayout, innerRadius: am5.percent(60) }));
    let series = chart.series.push(am5percent.PieSeries.new(root, { valueField: 'value', categoryField: 'category' }));
    series.set("colors", am5.ColorSet.new(root, {
      colors: [
        am5.color("#4CAF50"), // Green
        am5.color("#2196F3"), // Blue
        am5.color("#FFC107"), // Amber
        am5.color("#F44336"), // Red
        am5.color("#9C27B0")  // Purple
      ]
    }));
    series.data.setAll(dashboarddata.rst2);
    series.appear(1000, 100);

    let root2 = am5.Root.new('emiPaymentChart');
    // root2.setThemes([am5themes_Animated.new(root2)]);
    root2.setThemes([
      am5themes_Animated.new(root2),
      am5themes_Responsive.new(root2)
    ]);
    let chart2 = root2.container.children.push(am5xy.XYChart.new(root2, {
      panX: false,
      panY: false,
      wheelX: "panX",
      wheelY: "zoomX",
      paddingLeft: 0
    }));
    var cursor = chart2.set("cursor", am5xy.XYCursor.new(root2, {
      behavior: "zoomX"
    }));
    cursor.lineY.set("visible", false);

    // Create axes
    // https://www.amcharts.com/docs/v5/charts/xy-chart/axes/
    var xAxis = chart2.xAxes.push(am5xy.DateAxis.new(root2, {
      maxDeviation: 0,
      baseInterval: {
        timeUnit: "day",
        count: 1
      },
      renderer: am5xy.AxisRendererX.new(root2, {
        minorGridEnabled: true,
        minorLabelsEnabled: true
      }),
      tooltip: am5.Tooltip.new(root2, {})
    }));

    xAxis.get("renderer").set("minGridDistance", 80); // Makes columns wider


    xAxis.set("minorDateFormats", {
      "day": "dd",
      "month": "MM"
    });


    var yAxis = chart2.yAxes.push(am5xy.ValueAxis.new(root2, {
      renderer: am5xy.AxisRendererY.new(root2, {})
    }));


    // let xAxis = chart2.xAxes.push(am5xy.DateAxis.new(root2, { baseInterval: { timeUnit: 'month', count: 1 }, renderer: am5xy.AxisRendererX.new(root2, {}) }));
    // let yAxis = chart2.yAxes.push(am5xy.ValueAxis.new(root2, { renderer: am5xy.AxisRendererY.new(root2, {}) }));
    const series2 = chart2.series.push(am5xy.ColumnSeries.new(root2, {
      name: "Series",
      xAxis: xAxis,
      yAxis: yAxis,
      valueYField: "value",
      valueXField: "date",
      tooltip: am5.Tooltip.new(root2, {
        labelText: "{valueY}"
      })
    }));

    series2.columns.template.setAll({
      strokeOpacity: 0,
      width: am5.percent(60),   // Makes each column take up more horizontal space
      maxWidth: 40              // Absolute max column width
    });

    series2.set("sequencedInterpolation", false);

    // Add scrollbar
    // https://www.amcharts.com/docs/v5/charts/xy-chart/scrollbars/
    chart2.set("scrollbarX", am5.Scrollbar.new(root2, {
      orientation: "horizontal"
    }));

    const formattedData = dashboarddata.rst3.map(item => ({
      date: new Date(item.date).getTime(), // convert ISO to timestamp
      value: item.value,
    }));
    series2.data.setAll(formattedData);



    let lineSeries = chart2.series.push(
      am5xy.SmoothedXYLineSeries.new(root2, {
        name: "Expenses",
        xAxis: xAxis,
        yAxis: yAxis,
        valueYField: "value",
        valueXField: "date",
        tooltip: am5.Tooltip.new(root2, {
          pointerOrientation: "horizontal",
          labelText: "{name} at {valueX.formatDate()}: {valueY}"
        })
      })
    );


    lineSeries.strokes.template.setAll({
      strokeWidth: 2,
      stroke: am5.color(0x3f51b5), // optional: choose a line color
    });



    lineSeries.data.setAll(formattedData);

    lineSeries.bullets.push(function () {
      return am5.Bullet.new(root2, {
        sprite: am5.Circle.new(root2, {
          strokeWidth: 3,
          stroke: lineSeries.get("stroke"),
          radius: 5,
          fill: root2.interfaceColors.get("background")
        })
      });
    });

    chart.set("cursor", am5xy.XYCursor.new(root, {}));

    chart2.appear(1000, 100);

    series2.appear(1000);


    return () => {
      root.dispose();
      root2.dispose();
    };

  }, [dashboarddata]);

  return (
    <>
      {dashboarddata ? (
        <div className="container my-4">
          {/* Header */}
          <button className="btn btn-outline-secondary mb-3" onClick={onBack}>
            ← Back to Customer List
          </button>

          <div className="card p-4 mb-4 shadow-sm rounded-4">
            <div className="d-flex align-items-center">
              <img
                src={dashboarddata?.rst1[0]?.Photourl ? dashboarddata?.rst1[0]?.Photourl : profPic}
                alt="Customer"
                className="rounded-circle me-4"
                width="70"
                height="70"
              />
              <div className="flex-grow-1">
                <h5 className="mb-1">{dashboarddata?.rst1[0]?.FullName}</h5>
                <div className="row">
                  <div className="col-md-6">
                    <small className="text-muted d-block">Customer ID: {customerId}</small>
                    <small className="text-muted d-block">Branch: {dashboarddata?.rst1[0]?.Name || '-'}</small>
                    <small className="text-muted d-block">Gender: {dashboarddata?.rst1[0]?.Gender || '-'}</small>
                    <small className="text-muted d-block">National ID: {dashboarddata?.rst1[0]?.NationalId || '-'}</small>
                  </div>
                  <div className="col-md-4">
                    <small className="text-muted d-block">Email: {dashboarddata?.rst1[0]?.EmailId1 || '-'}</small>
                    <small className="text-muted d-block">Phone: {dashboarddata?.rst1[0]?.PhoneNo1 || '-'}</small>
                    <small className="text-muted d-block">Onboarded: {dashboarddata?.rst1[0]?.CustomerSince || '-'}</small>
                  </div>
                  <div className="col-md-2 text-end">
                    <div className="dropdown">
                      <button className="btn btn-primary dropdown-toggle" type="button" data-bs-toggle="dropdown">
                        Actions
                      </button>
                      <ul className="dropdown-menu dropdown-menu-end shadow-sm">
                        <li>
                          <button className="dropdown-item">
                            <Link to={"../OneScreen?scrid=148&stgid=349"} className="text-decoration-none text-dark">New Loan Request</Link>
                          </button>
                        </li>
                        <li>
                          <button className="dropdown-item">
                            <Link to={"../OneScreen?scrid=155&stgid=379"} className="text-decoration-none text-dark">Make Payment</Link>
                          </button>
                        </li>
                        <li>
                          <button className="dropdown-item">
                            <Link
                              to={"../OneScreen?scrid=136&stgid=308"}
                              state={{
                                txt_NationalIDNo: dashboarddata?.rst1[0]?.NationalId,
                                deeplink: true,
                                elementname: "txt_NationalIDNo",
                              }}
                              className="text-decoration-none text-dark"
                            >
                              Update Customer
                            </Link>
                          </button>
                        </li>
                        <li><button className="dropdown-item">Settlement</button></li>
                        <li><button className="dropdown-item">Loan Statement</button></li>
                      </ul>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Charts */}
          <div className="row g-4 mb-4">
            <div className="col-md-6">
              <div className="card p-3 shadow-sm rounded-4">
                <h6 className="mb-3">Loan Portfolio</h6>
                <div id="loanDistributionChart" style={{ height: '250px' }}></div>
              </div>
            </div>
            <div className="col-md-6">
              <div className="card p-3 shadow-sm rounded-4">
                <h6 className="mb-3">EMI Payment Trend</h6>
                <div id="emiPaymentChart" style={{ height: '250px' }}></div>
              </div>
            </div>
          </div>

          {/* Loan Details */}
          <div className="card p-3 mb-4 shadow-sm rounded-4">
            <h6 className="mb-3">Loan Accounts</h6>
            <div className="table-responsive">
              <table className="table table-hover table-sm align-middle">
                <thead className="table-light">
                  <tr>
                    <th>Loan ID</th>
                    <th>Type</th>
                    <th>Amount</th>
                    <th>Tenure</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboarddata?.rst4.map((item, idx) => (
                    <tr key={idx}>
                      <td>{item.LoanId}</td>
                      <td>{item.LoanTyp}</td>
                      <td>{item.LoanAmtScnd}</td>
                      <td>{item.Tenure}</td>
                      <td>
                        <span className={item.LoanStatus === "Active" ? "badge bg-success" : "badge bg-secondary"}>
                          {item.LoanStatus}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Payments and Alerts */}
          <div className="row g-4">
            <div className="col-md-6">
              <div className="card p-3 shadow-sm rounded-4">
                <h6 className="mb-3">Recent Payments</h6>
                <ul className="list-group list-group-flush">
                  {dashboarddata?.rst5.map((item, idx) => (
                    <li key={idx} className="list-group-item d-flex justify-content-between">
                      {item.ReceiptDate}
                      <span className="text-success fw-semibold">{item.ReceiptAmount}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
            <div className="col-md-6">
              <div className="card p-3 shadow-sm rounded-4">
                <h6 className="mb-3 text-danger">Alerts</h6>
                <ul className="list-group list-group-flush">
                  {dashboarddata?.rst6.map((item, idx) => (
                    <li key={idx} className="list-group-item text-danger">⚠️ {item.Alerts}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="text-center my-5">Loading customer details...</div>
      )}
    </>

  );
};

export default Customer360Dashboard;
